-- 店铺入驻申请本地演示数据（约 100 条，utf8mb4 中文虚构）
-- 同步写入 C 端事实表 + 平台监管投影，便于后台「店铺入驻申请」列表展示。
SET NAMES utf8mb4;

USE qixi_crm_business;
DELETE FROM qixi_crm_b_merchant_application WHERE id BETWEEN 980001 AND 980100;

USE qixi_crm_admin;
DELETE FROM qixi_crm_a_merchant_application WHERE source_application_id BETWEEN 980001 AND 980100 OR id BETWEEN 980001 AND 980100;

SELECT 'biz' AS db, COUNT(*) AS cnt FROM qixi_crm_business.qixi_crm_b_merchant_application WHERE id BETWEEN 980001 AND 980100
UNION ALL SELECT 'admin', COUNT(*) FROM qixi_crm_admin.qixi_crm_a_merchant_application WHERE source_application_id BETWEEN 980001 AND 980100;
SELECT status, COUNT(*) cnt FROM qixi_crm_admin.qixi_crm_a_merchant_application WHERE source_application_id BETWEEN 980001 AND 980100 GROUP BY status;